static int avgPrice(const Car &c) { return (int)(carValue(c) * pmult); }          // средняя рыночная цена
static void priceRange(const Car &c, int &lo, int &hi) { int a = avgPrice(c); lo = (int)(a * 0.85f); hi = (int)(a * 1.15f); }
static const char *condWord(int a) { return a < 25 ? "РАЗБИТА" : (a < 45 ? "ПЛОХОЕ" : (a < 65 ? "СРЕДНЕЕ" : (a < 85 ? "ХОРОШЕЕ" : "ОТЛИЧНОЕ"))); }
static int saleChance(int ask, const Car &c) {   // шанс продать объявление за день, %
  float r = ask / (float)imax(1, avgPrice(c));
  return r <= 0.85f ? 65 : (r <= 1.0f ? 40 : (r <= 1.1f ? 20 : (r <= 1.25f ? 8 : 2)));
}
static void genSellers() {
  for (int k = 0; k < NSEL; k++) {
    Seller &s2 = sellers[k];
    s2.has = rand() % 100 < 70;
    s2.nameIdx = rand() % 6;
    s2.tries = 0;
    s2.minR = frand(0.82f, 0.96f);
    s2.car = newCar(pickModel(), 25, 95);
    s2.car.dirt = (float)(rand() % 60);
    s2.car.ask = imax(80, (int)(avgPrice(s2.car) * frand(0.7f, 1.25f)));
    s2.floorP = (int)(s2.car.ask * s2.minR);
  }
}

