static void writeCar(FILE *f, const Car &c) {
  fprintf(f, "%d %d %d %d", c.model, c.col[0], c.col[1], c.col[2]);
  for (int p = 0; p < NP; p++) fprintf(f, " %d", c.cond[p]);
  fprintf(f, " %f %d %d %d %d %d %d %f %f %f %f %f %f %f %f %d %d\n", c.dirt, c.tune, c.client, c.nameIdx, c.dest, c.mask, c.reward,
          c.fuel, c.oil, c.filt, c.bfl, c.pads, c.disc, c.tires, c.bal, c.ask, c.rim);
}
static bool readCar(FILE *f, Car &c, int ver) {
  memset(&c, 0, sizeof c);
  if (fscanf(f, "%d %d %d %d", &c.model, &c.col[0], &c.col[1], &c.col[2]) != 4) return false;
  for (int p = 0; p < NP; p++) if (fscanf(f, "%d", &c.cond[p]) != 1) return false;
  if (fscanf(f, "%f %d %d %d %d %d %d %f %f %f %f %f %f %f %f", &c.dirt, &c.tune, &c.client, &c.nameIdx, &c.dest, &c.mask, &c.reward,
             &c.fuel, &c.oil, &c.filt, &c.bfl, &c.pads, &c.disc, &c.tires, &c.bal) != 15) return false;
  if (ver >= 8 && fscanf(f, "%d", &c.ask) != 1) return false;
  if (ver >= 9 && fscanf(f, "%d", &c.rim) != 1) return false;
  if (c.rim < 0 || c.rim > 0x1000000) c.rim = 0;
  if (c.model < 0 || c.model >= NMODEL) c.model = 0;
  c.nameIdx = clampi(c.nameIdx, 0, 5);
  c.dest = clampi(c.dest, 0, 3);
  for (int p = 0; p < NP; p++) c.cond[p] = clampi(c.cond[p], 0, 100);
  for (int q = 0; q < 3; q++) c.col[q] = clampi(c.col[q], 0, 255);
  c.dirt = clampf(c.dirt, 0, 100);
  c.tune = clampi(c.tune, 0, 3);
  c.client = c.client != 0 ? 1 : 0;
  c.mask = c.mask & 0x1FFF;
  c.reward = clampi(c.reward, 0, 100000000);
  c.ask = clampi(c.ask, 0, 100000000);
  c.fuel = clampf(c.fuel, 0, 100);
  c.oil = clampf(c.oil, 0, 100);
  c.filt = clampf(c.filt, 0, 100);
  c.bfl = clampf(c.bfl, 0, 100);
  c.pads = clampf(c.pads, 0, 100);
  c.disc = clampf(c.disc, 0, 100);
  c.tires = clampf(c.tires, 0, 100);
  c.bal = clampf(c.bal, 0, 100);
  return true;
}
// Сохраняем ВСЁ: деньги, гараж, эвакуатор, позицию, рынок, заказы, свалку. Пишем во временный файл, потом подменяем.
static void saveGame() {
  if (!gWorldLoaded) return;
  saveLic();
  char tmp[96];
  snprintf(tmp, sizeof tmp, "%s.tmp", SAVEF);
  FILE *f = fopen(pth(tmp), "w");
  if (!f) { say("Не удалось сохранить игру"); return; }
  fprintf(f, "%d %d %f %d %d\n", money, day, pmult, cur, (int)garage.size());
  for (size_t i = 0; i < garage.size(); i++) writeCar(f, garage[i]);
  fprintf(f, "%d\n", hasTow ? 1 : 0);
  if (hasTow) writeCar(f, towCar);
  fprintf(f, "%f\n", towFuel);
  fprintf(f, "%f %f %f %d\n", pPos.x, pPos.z, pHead, inTow ? 1 : 0);
  fprintf(f, "%f %f\n", fuelPrice, oilPrice);
  fprintf(f, "%d\n", (int)market.size());
  for (size_t i = 0; i < market.size(); i++) writeCar(f, market[i]);
  for (int i = 0; i < 3; i++) writeCar(f, orders[i].car);
  for (int i = 0; i < 5; i++) { fprintf(f, "%d\n", jslots[i].has ? 1 : 0); writeCar(f, jslots[i].car); }
  for (int i = 0; i < 3; i++) { fprintf(f, "%d %d\n", listed[i].has ? 1 : 0, listed[i].days); writeCar(f, listed[i].car); }
  fprintf(f, "%d\n", (int)buys.size());
  for (size_t i = 0; i < buys.size(); i++) fprintf(f, "%d %d %d %d %d\n", buys[i].nameIdx, buys[i].model, buys[i].minAvg, buys[i].price, buys[i].dest);
  for (int i = 0; i < 3; i++)
    fprintf(f, "%d %d %d %d %d %d\n", orders[i].type, orders[i].buy.nameIdx, orders[i].buy.model, orders[i].buy.minAvg, orders[i].buy.price, orders[i].buy.dest);
  for (int k = 0; k < NSEL; k++) {
    fprintf(f, "%d %d %d %d\n", sellers[k].has ? 1 : 0, sellers[k].nameIdx, sellers[k].floorP, sellers[k].tries);
    writeCar(f, sellers[k].car);
  }
  fprintf(f, "%f\n", dayT);
  fprintf(f, "%d %f %f %d\n", gWP.on ? 1 : 0, gWP.x, gWP.z, gWP.zone);
  fprintf(f, "%f\n", partMult);
  fprintf(f, "%d\n", (int)stock.size());
  for (size_t i = 0; i < stock.size(); i++) fprintf(f, "%d %d %d\n", stock[i].kind, stock[i].model, stock[i].qty);
  fprintf(f, "%d\n", (int)shipping.size());
  for (size_t i = 0; i < shipping.size(); i++) fprintf(f, "%d %d %f %f\n", shipping[i].kind, shipping[i].model, shipping[i].eta, shipping[i].total);
  if (fclose(f) == 0) { if (rename(pth(tmp), pth(SAVEF)) != 0) say("Не удалось сохранить игру"); }
}
static bool gotStock = false, gotPlayer = false, gotMarket = false, gotOrders = false, gotJunk = false, gotSellers = false, savedInTow = false;
static float savedX = -30, savedZ = -12, savedH = 0;
static bool loadFrom(const char *path, int ver) {
  FILE *f = fopen(pth(path), "r");
  if (!f && gBase[0] && gSlot == 0) f = fopen(path, "r");      // старые сохранения из рабочей папки (ccdroid)
  if (!f) return false;
  int n = 0;
  hasTow = false;
  if (fscanf(f, "%d %d %f %d %d", &money, &day, &pmult, &cur, &n) != 5 || n < 1 || n > 4) { fclose(f); return false; }
  garage.clear();
  for (int i = 0; i < n; i++) {
    Car c;
    if (!readCar(f, c, ver)) { fclose(f); garage.clear(); return false; }
    garage.push_back(c);
  }
  int ht = 0;
  if (fscanf(f, "%d", &ht) == 1 && ht) {
    Car t;
    if (readCar(f, t, ver)) { towCar = t; hasTow = true; }
  }
  if (fscanf(f, "%f", &towFuel) != 1) towFuel = 100;
  towFuel = clampf(towFuel, 0, 100);
  if (cur < 0 || cur >= (int)garage.size()) cur = 0;
  money = imax(0, money);
  day = imax(1, day);
  pmult = clampf(pmult, 0.5f, 2.0f);
  // остальное необязательно (старые сохранения его не содержат)
  do {
    float px, pz, ph, fp, op;
    int it, nm;
    if (fscanf(f, "%f %f %f %d", &px, &pz, &ph, &it) != 4) break;
    savedX = clampf(px, -220, 220); savedZ = clampf(pz, -220, 220); savedH = ph; savedInTow = it != 0; gotPlayer = true;
    if (fscanf(f, "%f %f", &fp, &op) != 2) break;
    fuelPrice = clampf(fp, 0.5f, 10.0f);
    oilPrice = clampf(op, 3.0f, 40.0f);
    if (fscanf(f, "%d", &nm) != 1 || nm < 0 || nm > 80) break;
    std::vector<Car> mk;
    bool ok = true;
    for (int i = 0; i < nm; i++) { Car c; if (!readCar(f, c, ver)) { ok = false; break; } mk.push_back(c); }
    if (!ok) break;
    market = mk; mIdx = 0; dPos = 0; gotMarket = true;
    Order to[3];
    memset(to, 0, sizeof to);
    for (int i = 0; i < 3; i++) { if (!readCar(f, to[i].car, ver)) { ok = false; break; } to[i].nameIdx = to[i].car.nameIdx; }
    if (!ok) break;
    for (int i = 0; i < 3; i++) orders[i] = to[i];
    oSel = 0; gotOrders = true;
    JSlot tj[5];
    for (int i = 0; i < 5; i++) {
      int has = 0;
      if (fscanf(f, "%d", &has) != 1 || !readCar(f, tj[i].car, ver)) { ok = false; break; }
      tj[i].has = has != 0;
    }
    if (!ok) break;
    for (int i = 0; i < 5; i++) {
      jslots[i].has = tj[i].has; jslots[i].car = tj[i].car;
      jslots[i].x = JX[i]; jslots[i].z = JZ[i]; jslots[i].h = JH[i];
    }
    gotJunk = true;
    if (ver < 10) break;
    Listing tl[3];
    memset(tl, 0, sizeof tl);
    for (int i = 0; i < 3 && ok; i++) {
      int has = 0, dys = 0;
      if (fscanf(f, "%d %d", &has, &dys) != 2 || !readCar(f, tl[i].car, ver)) { ok = false; break; }
      tl[i].has = has != 0; tl[i].days = clampi(dys, 0, 100000);
    }
    if (!ok) break;
    for (int i = 0; i < 3; i++) listed[i] = tl[i];
    int nb = 0;
    if (fscanf(f, "%d", &nb) != 1 || nb < 0 || nb > 3) break;
    std::vector<BuyReq> tb;
    for (int i = 0; i < nb && ok; i++) {
      BuyReq r;
      if (fscanf(f, "%d %d %d %d %d", &r.nameIdx, &r.model, &r.minAvg, &r.price, &r.dest) != 5) { ok = false; break; }
      r.nameIdx = clampi(r.nameIdx, 0, 5); r.model = clampi(r.model, 0, NMODEL - 1); r.dest = clampi(r.dest, 0, 3);
      tb.push_back(r);
    }
    if (!ok) break;
    buys = tb;
    for (int i = 0; i < 3 && ok; i++) {
      int ty = 0;
      BuyReq r;
      if (fscanf(f, "%d %d %d %d %d %d", &ty, &r.nameIdx, &r.model, &r.minAvg, &r.price, &r.dest) != 6) { ok = false; break; }
      r.nameIdx = clampi(r.nameIdx, 0, 5); r.model = clampi(r.model, 0, NMODEL - 1); r.dest = clampi(r.dest, 0, 3); r.minAvg = clampi(r.minAvg, 0, 100);
      orders[i].type = ty != 0 ? 1 : 0; orders[i].buy = r;
    }
    if (!ok) break;
    Seller ts[NSEL];
    memset(ts, 0, sizeof ts);
    for (int k = 0; k < NSEL && ok; k++) {
      int has = 0, nmi = 0, fl = 0, tr = 0;
      if (fscanf(f, "%d %d %d %d", &has, &nmi, &fl, &tr) != 4 || !readCar(f, ts[k].car, ver)) { ok = false; break; }
      ts[k].has = has != 0; ts[k].nameIdx = clampi(nmi, 0, 5); ts[k].floorP = clampi(fl, 0, 100000000); ts[k].tries = clampi(tr, 0, 3); ts[k].minR = 0.9f;
    }
    if (!ok) break;
    for (int k = 0; k < NSEL; k++) sellers[k] = ts[k];
    gotSellers = true;
    float dt2 = 0;
    if (fscanf(f, "%f", &dt2) == 1) dayT = clampf(dt2, 0.0f, 239.0f);
    { int on = 0, zn = -1; float wx = 0, wz = 0;
      if (fscanf(f, "%d %f %f %d", &on, &wx, &wz, &zn) == 4) { gWP.on = on != 0; gWP.x = clampf(wx, -225.0f, 225.0f); gWP.z = clampf(wz, -225.0f, 225.0f); gWP.zone = (zn >= -1 && zn < 9 + NSEL) ? zn : -1; }
      if (ver >= 11) {
        float pm = 1.0f;
        int ns = 0, nh = 0;
        if (fscanf(f, "%f", &pm) == 1) partMult = clampf(pm, 0.5f, 2.0f);
        if (fscanf(f, "%d", &ns) == 1 && ns >= 0 && ns < 300) {
          std::vector<StockItem> tstock;
          for (int i = 0; i < ns; i++) {
            StockItem si;
            if (fscanf(f, "%d %d %d", &si.kind, &si.model, &si.qty) != 3) break;
            if (si.kind < 0 || si.kind >= NK || si.model < 0 || si.model >= NMODEL || si.qty <= 0) continue;
            si.qty = clampi(si.qty, 1, 999);
            tstock.push_back(si);
          }
          stock = tstock;
          gotStock = true;
        }
        if (fscanf(f, "%d", &nh) == 1 && nh >= 0 && nh < 40) {
          std::vector<PartOrder> th;
          for (int i = 0; i < nh; i++) {
            PartOrder o;
            if (fscanf(f, "%d %d %f %f", &o.kind, &o.model, &o.eta, &o.total) != 4) break;
            if (o.kind < 0 || o.kind >= NK || o.model < 0 || o.model >= NMODEL) continue;
            th.push_back(o);
          }
          shipping = th;
        }
      }
    }
  } while (0);
  fclose(f);
  return true;
}
static bool loadGame() {
  if (loadFrom(SAVEF, 11)) return true;
  if (gSlot != 0) return false;                                // у остальных миров только текущий формат
  if (loadFrom("mechanic3d10.sav", 10)) return true;
  if (loadFrom("mechanic3d9.sav", 9)) return true;
  if (loadFrom("mechanic3d8.sav", 8)) return true;   // сохранения старых версий
  return loadFrom("mechanic3d7.sav", 7);
}
static void setSlot(int s) {
  gSlot = s;
  if (s == 0) snprintf(gSaveName, sizeof gSaveName, "mechanic3d11.sav");
  else snprintf(gSaveName, sizeof gSaveName, "mechanic3d11_s%d.sav", s);
}
static bool slotInfo(int s, int &m, int &d, int &n) {          // деньги, день, число машин из файла мира (без загрузки)
  char nm[64];
  if (s == 0) snprintf(nm, sizeof nm, "mechanic3d11.sav"); else snprintf(nm, sizeof nm, "mechanic3d11_s%d.sav", s);
  FILE *f = fopen(pth(nm), "r");
  if (!f && gBase[0] && s == 0) f = fopen(nm, "r");
  if (!f) return false;
  float pm = 1; int cu = 0;
  int r = fscanf(f, "%d %d %f %d %d", &m, &d, &pm, &cu, &n);
  fclose(f);
  return r == 5 && n >= 1;
}
static void saveLic() {                                       // день получения прав лежит в отдельном файле рядом с миром
  char nm[96];
  snprintf(nm, sizeof nm, "%s.lic", gSaveName);
  FILE *f = fopen(pth(nm), "w");
  if (!f) return;
  fprintf(f, "%d\n", licenseDay);
  fclose(f);
}
static void loadLic() {
  char nm[96];
  snprintf(nm, sizeof nm, "%s.lic", gSaveName);
  FILE *f = fopen(pth(nm), "r");
  int d = 0;
  if (f) { if (fscanf(f, "%d", &d) != 1) d = day; fclose(f); } else d = day;      // старый мир без файла: права действительны с сегодня
  licenseDay = clampi(d, 1, day);
}
static void newGame() {
  money = 500; day = 1; pmult = 1.0f; cur = 0;
  garage.clear();
  stock.clear(); shipping.clear(); partMult = 1.0f;
  stockAdd(6, 0, 1); stockAdd(7, 0, 1);      // стартовый набор: масло и фильтр
  Car c = newCar(0, 30, 60);
  c.dirt = 30;
  c.fuel = 100;
  c.oil = 70;
  c.filt = 75;
  c.bfl = 80;
  c.pads = 70;
  c.disc = 85;
  c.tires = 75;
  c.bal = 85;
  towFuel = 100;
  garage.push_back(c);
}
static void newDay() {
  day++;
  dayT = 0;
  pmult = frand(0.85f, 1.2f);
  fuelPrice = frand(1.6f, 2.8f);
  oilPrice = frand(9.0f, 16.0f);
  partMult = frand(0.85f, 1.2f);
  int sold = 0, total = 0;
  for (int i = 0; i < 3; i++)
    if (listed[i].has) {
      listed[i].days++;
      if (rand() % 100 < saleChance(listed[i].car.ask, listed[i].car)) {
        money += listed[i].car.ask; total += listed[i].car.ask; sold++; listed[i].has = false;
      }
    }
  genMarket();
  genOrders();
  genJunk();
  genSellers();
  char m[96];
  if (sold) { snprintf(m, sizeof m, "ПРОДАНО МАШИН: %d, +$%d", sold, total); say(m); }
  else say("НОВЫЙ ДЕНЬ");
  if (licenseExpired()) say("Права просрочены! Полиция оштрафует на 50%. Сдай экзамен");
  else if (licenseLeft() <= 3) { char lb[64]; snprintf(lb, sizeof lb, "Права истекают через %d дн.", licenseLeft()); say(lb); }
  saveGame();
}

// ---------- Мир ----------
struct Box { float x, z, w, d, y0, h; u32 col; bool solid; };
struct Tree { float x, z, h; };
struct Zone { float x, z; u32 col; int kind; const char *label; };
static std::vector<Box> blds;
static std::vector<Tree> trees;
enum { NZONE = 9 + NSEL };
static Zone zones[NZONE];
enum { NROAD = 3 };
static const float ROADS[NROAD] = {-120, 0, 120};      // дороги через 120 м (было каждые 60 м): меньше перекрёстков и светофоров, длинные прямые
static const float RHALF = 7.0f, WLIM = 225.0f, REND = 210.0f;
static const float DEST[4][2] = {{30, 14}, {96, -14}, {-96, 14}, {30, -74}};

static unsigned wseed = 12345;
static float wrand(float a, float b) {
  wseed = wseed * 1664525u + 1013904223u;
  return a + (b - a) * ((wseed >> 8) & 0xFFFF) / 65535.0f;
}
static void addBox(float x, float z, float w, float d, float y0, float h, u32 col, bool solid) {
  Box b; b.x = x; b.z = z; b.w = w; b.d = d; b.y0 = y0; b.h = h; b.col = col; b.solid = solid;
  blds.push_back(b);
}
static bool nearRoad(float x, float z, float rx, float rz, float m) {
  for (int i = 0; i < NROAD; i++) {
    if (fabsf(x - ROADS[i]) < RHALF + rx + m) return true;
    if (fabsf(z - ROADS[i]) < RHALF + rz + m) return true;
  }
  return false;
}
static bool nearZones(float x, float z, float rx, float rz) {
  for (int i = 0; i < NZONE; i++) {
    float dx = fmaxv(0, fabsf(x - zones[i].x) - rx), dz = fmaxv(0, fabsf(z - zones[i].z) - rz);
    if (dx * dx + dz * dz < 13 * 13) return true;
  }
  return false;
}
static bool inYard(float x, float z, float rx, float rz, float m) {
  return fabsf(x - 96) < 13.5f + rx + m && fabsf(z - 34) < 14 + rz + m;
}
static bool hitsBoxes(float x, float z, float rx, float rz, float m) {
  for (size_t i = 0; i < blds.size(); i++) {
    if (!blds[i].solid) continue;
    if (fabsf(x - blds[i].x) < rx + blds[i].w / 2 + m && fabsf(z - blds[i].z) < rz + blds[i].d / 2 + m) return true;
  }
  return false;
}
// ---------- Дорожные знаки ----------
// type: 0 стоп, 1 уступи дорогу, 2 ограничение скорости, 3 главная дорога, 4 пешеходный переход,
//       5 парковка, 6 дорожные работы, 7 больница (синий крест), 8 осторожно дети, 9 опасный поворот; 3 - главная дорога (без «кирпича» и односторонки)
static void addSign(float x, float z, int axis, int dir, int type) {
  bool alongZ = (axis == 0);                       // едут вдоль z: табличка тонкая по z
  float fx = alongZ ? 0.0f : -(float)dir, fz = alongZ ? -(float)dir : 0.0f;   // от знака к водителю
  const u32 WH = RGB(255, 255, 252), RD = RGB(242, 48, 48), BL = RGB(52, 122, 235), YL = RGB(255, 216, 50), BK = RGB(30, 30, 34);   // светлее: лицо знака часто в тени
  addBox(x, z, 0.14f, 0.14f, 0, 2.75f, RGB(140, 140, 148), true);
  // часть знака: lat - смещение поперёк движения, w - ширина, y0/h - высота, depth - выступ к водителю
  struct P { float lat, w, y0, h; u32 col; float depth; };
  P parts[8]; int n = 0;
  auto add = [&](float lat, float w, float y0, float h, u32 col, float depth) { parts[n].lat = lat; parts[n].w = w; parts[n].y0 = y0; parts[n].h = h; parts[n].col = col; parts[n].depth = depth; n++; };
  switch (type) {
    case 0: add(0, 1.06f, 1.97f, 1.06f, WH, 0.0f); add(0, 0.96f, 2.02f, 0.96f, RD, 0.03f); add(0, 0.7f, 2.2f, 0.12f, WH, 0.06f); add(0, 0.7f, 2.42f, 0.12f, WH, 0.06f); add(0, 0.7f, 2.64f, 0.12f, WH, 0.06f); break;
    case 1: add(0, 1.14f, 1.97f, 1.0f, RD, 0.0f); add(0, 0.72f, 2.22f, 0.58f, WH, 0.04f); add(0, 0.3f, 2.5f, 0.2f, RD, 0.07f); break;
    case 2: add(0, 1.04f, 1.97f, 1.04f, RD, 0.0f); add(0, 0.76f, 2.11f, 0.76f, WH, 0.03f); add(-0.16f, 0.1f, 2.28f, 0.42f, BK, 0.06f); add(0.02f, 0.12f, 2.28f, 0.42f, BK, 0.06f); add(0.17f, 0.1f, 2.28f, 0.42f, BK, 0.06f); break;
    case 3: add(0, 1.06f, 1.97f, 1.06f, WH, 0.0f); add(0, 0.86f, 2.07f, 0.86f, YL, 0.03f); add(0, 0.5f, 2.25f, 0.5f, WH, 0.06f); add(0, 0.3f, 2.35f, 0.3f, YL, 0.08f); break;   // главная дорога (вместо «кирпича»)
    case 4: add(0, 1.04f, 1.97f, 1.04f, BL, 0.0f); add(0, 0.8f, 2.1f, 0.8f, WH, 0.03f); add(-0.24f, 0.13f, 2.14f, 0.72f, BK, 0.06f); add(0.0f, 0.13f, 2.14f, 0.72f, BK, 0.06f); add(0.24f, 0.13f, 2.14f, 0.72f, BK, 0.06f); break;
    case 5: add(0, 1.04f, 1.97f, 1.04f, BL, 0.0f); add(-0.15f, 0.14f, 2.12f, 0.74f, WH, 0.04f); add(0.05f, 0.4f, 2.5f, 0.14f, WH, 0.04f); add(0.05f, 0.4f, 2.3f, 0.14f, WH, 0.04f); add(0.2f, 0.14f, 2.3f, 0.34f, WH, 0.04f); break;
    case 6: add(0, 1.1f, 1.97f, 1.0f, YL, 0.0f); add(0, 0.92f, 2.05f, 0.84f, BK, 0.03f); add(0, 0.78f, 2.12f, 0.7f, YL, 0.05f); add(0, 0.14f, 2.25f, 0.34f, BK, 0.08f); add(0, 0.14f, 2.16f, 0.07f, BK, 0.08f); break;
    case 7: add(0, 1.04f, 1.97f, 1.04f, BL, 0.0f); add(0, 0.62f, 2.38f, 0.16f, WH, 0.04f); add(0, 0.16f, 2.15f, 0.62f, WH, 0.04f); break;   // больница/помощь: белый крест (вместо одностороннего движения)
    case 8: add(0, 1.04f, 1.97f, 1.04f, YL, 0.0f); add(0, 0.9f, 2.04f, 0.9f, BK, 0.03f); add(0, 0.78f, 2.1f, 0.78f, YL, 0.05f); add(-0.12f, 0.12f, 2.16f, 0.4f, BK, 0.08f); add(0.14f, 0.14f, 2.16f, 0.28f, BK, 0.08f); break;
    default: add(0, 1.04f, 1.97f, 1.04f, YL, 0.0f); add(0, 0.9f, 2.04f, 0.9f, BK, 0.03f); add(0, 0.78f, 2.1f, 0.78f, YL, 0.05f); add(0.1f, 0.32f, 2.5f, 0.12f, BK, 0.08f); add(0.22f, 0.12f, 2.2f, 0.4f, BK, 0.08f); break;
  }
  for (int i = 0; i < n; i++) {
    float lx = alongZ ? parts[i].lat : 0.0f, lz = alongZ ? 0.0f : parts[i].lat;
    float px = x + lx + fx * (0.08f + parts[i].depth), pz = z + lz + fz * (0.08f + parts[i].depth);
    float W = alongZ ? parts[i].w : 0.05f, D = alongZ ? 0.05f : parts[i].w;
    addBox(px, pz, W, D, parts[i].y0, parts[i].h, parts[i].col, false);
  }
}
static void addSigns() {
  const float side = RHALF + 1.0f;
  int count = 0;
  for (int ir = 0; ir < NROAD; ir++)
    for (int ic = 0; ic < NROAD; ic++) {
      for (int axis = 0; axis < 2; axis++)
        for (int dsg = 0; dsg < 2; dsg++) {
          int dir = dsg ? 1 : -1;
          int h = (ir * 7 + ic * 13 + axis * 5 + dsg * 3 + 11) % 10;
          if (h >= 6) continue;                          // знак не на каждом подъезде
          int type = (ir * 3 + ic * 5 + axis * 2 + dsg + count) % 10;
          float c = axis == 0 ? ROADS[ic] : ROADS[ic];  // координата поперечной дороги
          float r = ROADS[ir];                          // координата дороги, по которой едут
          float t = c - dir * (RHALF + 7.0f);           // за 7 м до края перекрёстка
          if (fabsf(t) > REND - 6.0f) continue;
          float sx, sz;
          if (axis == 0) { sx = r + dir * side; sz = t; }          // едут вдоль z, полоса x = r + dir*...
          else { sx = t; sz = r - dir * side; }                    // едут вдоль x, полоса z = r - dir*...
          addSign(sx, sz, axis, dir, type);
          count++;
        }
    }
  // знаки по ходу дороги между перекрёстками (ограничение скорости, парковка, дорожные работы)
  for (int ir = 0; ir < NROAD; ir++)
    for (int seg = 0; seg < NROAD - 1; seg++) {
      float mid = (ROADS[seg] + ROADS[seg + 1]) * 0.5f;
      int axis = (ir + seg) & 1, dir = ((ir + seg) & 2) ? 1 : -1;
      int type = (ir * 4 + seg * 3 + 2) % 10;
      float r = ROADS[ir];
      float sx = axis == 0 ? r + dir * side : mid, sz = axis == 0 ? mid : r - dir * side;
      addSign(sx, sz, axis, dir, type);
    }
}

static void addLights() {                          // столбы светофоров (твёрдые) на каждом перекрёстке, по одному на подъезд
  for (int ix = 0; ix < NROAD; ix++)
    for (int iz = 0; iz < NROAD; iz++)
      for (int axis = 0; axis < 2; axis++)
        for (int dsg = 0; dsg < 2; dsg++) {
          int dir = dsg ? 1 : -1;
          float cx = ROADS[ix], cz = ROADS[iz];
          float px = axis == 0 ? cx + dir * (RHALF + 1.1f) : cx - dir * (RHALF + 1.4f);
          float pz = axis == 0 ? cz - dir * (RHALF + 1.4f) : cz - dir * (RHALF + 1.1f);
          addBox(px, pz, 0.16f, 0.16f, 0, 3.3f, RGB(70, 72, 80), true);
        }
}
