// Плоский диск (только внешняя грань): для тёмных арок, боковых стенок не видно
static void drawDiscCap(V3 c, V3 ax, V3 ay, V3 az, float r, int s2, u32 col) {
  const int N = 10;
  V3 cap[N];
  for (int i = 0; i < N; i++) {
    float t = 6.2831853f * i / N;
    cap[i] = c + ay * (r * cosf(t)) + az * (r * sinf(t));
  }
  faceN(cap, N, ax * (float)s2, col, true);
}
