    int bw = (w - fs * 3) / 2;
    R rd = {x, y, bw, bh}, rf = {x + bw + fs * 3, y, bw, bh};
    bool holdD = P.down && inR(rd, P.x, P.y) && inR(rd, P.sx, P.sy) && car.oil > 0.05f;
    if (car.oil <= 10.0f) oilFillMode = true;
    if (car.oil >= 99.9f) oilFillMode = false;
    static bool oilPaid = false;
    bool canFill = oilFillMode && (haveOil > 0 || oilPaid);
