    button(rf.x, rf.y, rf.w, rf.h, holdF ? "ЗАЛИВАЮ...\nДЕРЖИ" : (canFill ? "Держи -\nзалить новое" : (oilFillMode ? "Нет масла!\nЗакажи в деталях" : "Залить новое\n(сначала слей)")),
           canFill && car.oil < 99.9f, holdF ? RGB(90, 200, 120) : RGB(60, 150, 90));
