    snprintf(b, sizeof b, "%s", fModel < 0 ? "ЛЮБАЯ МОДЕЛЬ" : MOD[fModel].name);
    fitText(b, w - aw * 4 - fs * 8);
    drawText(x + w / 2, y + fs * 3, b, fs, RGB(240, 240, 250), 1);
    y += step;
    // состояние от
    if (button(x, y, aw, ch, "-", true, RGB(50, 54, 66))) fMinCond = imax(0, fMinCond - 10);
    if (button(x + w - aw, y, aw, ch, "+", true, RGB(50, 54, 66))) fMinCond = imin(90, fMinCond + 10);
    if (fMinCond == 0) snprintf(b, sizeof b, "СОСТОЯНИЕ: ЛЮБОЕ");
    else snprintf(b, sizeof b, "СОСТОЯНИЕ ОТ %d%%", fMinCond);
    fitText(b, w - aw * 2 - fs * 4);
    drawText(x + w / 2, y + fs * 3, b, fs, RGB(200, 220, 255), 1);
