    drawText(x, y, b, fs, RGB(200, 220, 255), 0);
    y += fs * 10;
    snprintf(b, sizeof b, "СРЕДНЯЯ ЦЕНА $%d", av);
    drawText(x, y, b, fs, RGB(255, 235, 120), 0);
    y += fs * 10;
    snprintf(b, sizeof b, "ДИАПАЗОН $%d-$%d", lo, hi);
    fitText(b, w);
