static const int NQ = (int)(sizeof(QBANK) / sizeof(QBANK[0]));
enum { EXQ = 10, EXMAXWRONG = 2 };
static int exQ[EXQ], exPerm[EXQ][4], exI = 0, exWrong = 0, exAns = -1;
static bool exDone = false;
static void startExam() {
  int used[64] = {0};
  for (int i = 0; i < EXQ; i++) {
    int q;
    do { q = rand() % NQ; } while (used[q]);
    used[q] = 1; exQ[i] = q;
    int p[4] = {0, 1, 2, 3};
    for (int k = 3; k > 0; k--) { int j = rand() % (k + 1); int t = p[k]; p[k] = p[j]; p[j] = t; }
    for (int k = 0; k < 4; k++) exPerm[i][k] = p[k];
  }
  exI = 0; exWrong = 0; exAns = -1; exDone = false;
  state = ST_EXAM; pSpeed = 0; stickOn = false; stX = stY = 0; gWP.on = gWP.on;
}
// вывод текста с переносом по словам; возвращает y после последней строки
static int wrapText(int x, int y, int w, const char *s, int sc, u32 col) {
  char line[256]; int n = 0;
  const char *p = s;
  line[0] = 0;
  while (*p) {
    const char *e = p; while (*e && *e != ' ') e++;
    char word[96]; int wl = (int)(e - p); if (wl > 90) wl = 90; memcpy(word, p, wl); word[wl] = 0;
    char test[256]; snprintf(test, sizeof test, n ? "%s %s" : "%s%s", line, word);
    if (n && textW(test, sc) > w) { drawText(x, y, line, sc, col, 0); y += 9 * sc + sc * 2; snprintf(line, sizeof line, "%s", word); }
    else snprintf(line, sizeof line, "%s", test);
    n++;
    p = e; while (*p == ' ') p++;
  }
  if (line[0]) { drawText(x, y, line, sc, col, 0); y += 9 * sc + sc * 2; }
  return y;
}
// подпись кнопки с переносом на 2-3 строки (кнопка рисует строки по '\n')
static void wrapLabel(const char *s, int maxw, char *out, int outn) {
  char lines[3][64]; int ln = 0; lines[0][0] = 0;
  const char *p = s;
  while (*p && ln < 3) {
    const char *e = p; while (*e && *e != ' ') e++;
    char word[64]; int wl = (int)(e - p); if (wl > 60) wl = 60; memcpy(word, p, wl); word[wl] = 0;
    char test[128]; snprintf(test, sizeof test, lines[ln][0] ? "%s %s" : "%s%s", lines[ln], word);
    if (lines[ln][0] && (textW(test, fs) > maxw || strlen(test) > 62)) { if (ln == 2) break; ln++; snprintf(lines[ln], sizeof lines[ln], "%s", word); }
    else snprintf(lines[ln], sizeof lines[ln], "%s", test);
    p = e; while (*p == ' ') p++;
  }
  out[0] = 0;
  for (int i = 0; i <= ln && i < 3; i++) { if (i) strncat(out, "\n", outn - strlen(out) - 1); strncat(out, lines[i], outn - strlen(out) - 1); }
}
static void examScreen(float dt) {
  (void)dt;
  fillRect(0, 0, IW, IH, RGB(22, 24, 32));
  int pad = fs * 4, x = pad, w = IW - pad * 2, y = pad;
  char b[160];
  if (!exDone) {
    snprintf(b, sizeof b, "ЭКЗАМЕН НА ПРАВА   вопрос %d из %d   ошибок %d (можно %d)", exI + 1, EXQ, exWrong, EXMAXWRONG);
    drawText(x, y, b, fs, RGB(255, 210, 120), 0);
    y += fs * 13;
    const Quiz &q = QBANK[exQ[exI]];
    y = wrapText(x, y, w, q.q, fs + 1, RGB(235, 238, 245));
    y += fs * 4;
    int bh = fs * 17, gap = fs * 2;
    for (int k = 0; k < 4; k++) {
      int orig = exPerm[exI][k];
      char lab[200]; wrapLabel(q.o[orig], w - fs * 6, lab, sizeof lab);
      u32 col = RGB(70, 78, 110);
      if (exAns >= 0) { if (orig == q.ok) col = RGB(50, 150, 80); else if (k == exAns) col = RGB(190, 60, 60); else col = RGB(52, 56, 72); }
      if (button(x, y, w, bh, lab, true, col) && exAns < 0) {
        exAns = k;
        if (orig != q.ok) exWrong++;
      }
      y += bh + gap;
    }
    if (exAns >= 0) {
      bool last = exI == EXQ - 1;
      int bw = fs * 80;
      if (button(IW - pad - bw, IH - pad - fs * 16, bw, fs * 16, last ? "Результат" : "Далее", true, RGB(60, 110, 200))) {
        if (last) {
          exDone = true;
          if (exWrong <= EXMAXWRONG) { licenseDay = day; saveGame(); say("Права получены! Действуют 30 дней"); }
        } else { exI++; exAns = -1; }
      }
    }
  } else {
    bool ok = exWrong <= EXMAXWRONG;
    drawText(IW / 2, y + fs * 8, ok ? "ЭКЗАМЕН СДАН!" : "ЭКЗАМЕН НЕ СДАН", fs + 3, ok ? RGB(120, 240, 130) : RGB(255, 100, 90), 1);
    snprintf(b, sizeof b, "Правильных ответов: %d из %d (ошибок %d, можно не больше %d)", EXQ - exWrong, EXQ, exWrong, EXMAXWRONG);
    drawText(IW / 2, y + fs * 30, b, fs, RGB(200, 205, 220), 1);
    if (ok) { snprintf(b, sizeof b, "Права действуют 30 дней: до дня %d", day + 30); drawText(IW / 2, y + fs * 42, b, fs, RGB(140, 220, 150), 1); }
    else drawText(IW / 2, y + fs * 42, "Без прав полиция оштрафует на 50% баланса: пересдай", fs, RGB(255, 190, 120), 1);
    int bw = imin(IW - pad * 2, fs * 120), bx = IW / 2 - bw / 2, by = y + fs * 62, bh = fs * 17;
    if (!ok) { if (button(bx, by, bw, bh, "Пересдать", true, RGB(60, 110, 200))) startExam(); by += bh + fs * 3; }
    if (button(bx, by, bw, bh, "В игру", true, RGB(60, 150, 90))) { state = ST_WORLD; saveGame(); }
  }
  toast(IW / 2, IH - fs * 12);
}
static void menuGame(float dt) {
  fillRect(0, 0, IW, IH, RGB(24, 26, 34));
  int pad = fs * 3, bw = imin(IW - pad * 2, fs * 160), x = IW / 2 - bw / 2, bh = fs * 15, gap = fs * 3, y = pad;
  char b[96];
  drawText(IW / 2, y + fs, "МЕНЮ", fs + 1, RGB(255, 210, 120), 1);
  y += fs * 16;
  if (menuPage == 0) {
    {   // кнопок много: подгоняем высоту под экран
      int nb = 13 + (rotMode ? 1 : 0);
      bh = imin(bh, imax(fs * 9, (IH - y - fs * 12) / nb - gap));
    }
    if (button(x, y, bw, bh, "Продолжить", true, RGB(60, 150, 90))) state = ST_WORLD;
    y += bh + gap;
    if (button(x, y, bw, bh, "Сохранить игру", true, RGB(60, 110, 200))) { saveGame(); say("ИГРА СОХРАНЕНА"); }
    y += bh + gap;
    if (rotMode) {
      if (button(x, y, bw, bh, "Повернуть экран", true, RGB(90, 96, 120))) { rotDir = -rotDir; saveCfg(); }
      y += bh + gap;
    }
    if (button(x, y, bw, bh, "Поля экрана", true, RGB(90, 96, 120))) menuPage = 2;
    y += bh + gap;
    {
      static const char *qn[3] = {"Графика: низкая", "Графика: средняя", "Графика: высокая"};
      if (button(x, y, bw, bh, qn[quality], true, RGB(90, 96, 120))) { quality = (quality + 1) % 3; saveCfg(); gApplyQ = true; }
      y += bh + gap;
    }
    if (button(x, y, bw, bh, aaOn ? "Сглаживание: вкл" : "Сглаживание: выкл", true, aaOn ? RGB(60, 130, 90) : RGB(90, 96, 120))) { aaOn = !aaOn; saveCfg(); }
    y += bh + gap;
    if (button(x, y, bw, bh, fpsOn ? "Счётчик FPS: вкл" : "Счётчик FPS: выкл", true, fpsOn ? RGB(60, 130, 90) : RGB(90, 96, 120))) { fpsOn = !fpsOn; saveCfg(); }
    y += bh + gap;
    if (button(x, y, bw, bh, autoPerf ? "Авто-упрощение: вкл" : "Авто-упрощение: выкл", true, autoPerf ? RGB(60, 130, 90) : RGB(90, 96, 120))) { autoPerf = !autoPerf; if (!autoPerf) gPerf = 0; saveCfg(); }
    y += bh + gap;
    if (button(x, y, bw, bh, "Свои модели (OBJ)", true, RGB(90, 96, 120))) menuPage = 3;
    y += bh + gap;
    if (button(x, y, bw, bh, "Новая игра", true, RGB(200, 120, 40))) { menuPage = 1; resetProg = 0; }
    y += bh + gap;
    {
      char lb[64];
      if (licenseExpired()) snprintf(lb, sizeof lb, "Права просрочены: сдать экзамен");
      else snprintf(lb, sizeof lb, "Сдать экзамен на права (осталось %d дн.)", licenseLeft());
      if (button(x, y, bw, bh, lb, true, licenseExpired() ? RGB(200, 80, 60) : RGB(90, 96, 120))) startExam();
      y += bh + gap;
    }
    if (button(x, y, bw, bh, "В меню миров", true, RGB(90, 96, 120))) { saveGame(); gWorldLoaded = false; taxi.on = false; taxi.st = 0; state = ST_TITLE; titleConf = -1; }
    y += bh + gap;
    if (button(x, y, bw, bh, "Выйти из игры", true, RGB(190, 60, 60))) { saveGame(); gQuit = true; }
    y += bh + gap;
    snprintf(b, sizeof b, "ДЕНЬГИ $%d   ДЕНЬ %d   МАШИН %d", money, day, (int)garage.size());
    drawText(IW / 2, y, b, fs, RGB(150, 160, 185), 1);
  } else if (menuPage == 3) {
    drawText(IW / 2, y, "СВОИ 3D-МОДЕЛИ (OBJ)", fs + 1, RGB(255, 210, 120), 1);
    y += fs * 12;
    drawText(IW / 2, y, "ФАЙЛЫ: ПАПКА models, ОПИСАНИЕ: mechanic3d_models.txt", fs, RGB(170, 190, 220), 1);
    y += fs * 9;
    {
      char cw[160] = "?", cl[200];
#ifdef HAVE_GETCWD
      if (!getcwd(cw, sizeof cw)) strcpy(cw, "?");
#endif
      snprintf(cl, sizeof cl, "ПАПКА ИГРЫ: %s", cw);
      fitText(cl, IW - pad * 2);
      drawText(pad, y, cl, fs, RGB(255, 235, 140), 0);
      y += fs * 9;
#ifdef HAVE_GETCWD
      bool okx = access("/storage/emulated/0/Download/mechanic3d", R_OK) == 0 || access("/sdcard/Download/mechanic3d", R_OK) == 0;
      snprintf(cl, sizeof cl, "ИЛИ ПАПКА Download/mechanic3d: %s", okx ? "ЕСТЬ, ИГРА ЕЁ ВИДИТ" : "НЕТ ИЛИ НЕТ ДОСТУПА");
      fitText(cl, IW - pad * 2);
      drawText(pad, y, cl, fs, okx ? RGB(150, 235, 160) : RGB(170, 180, 205), 0);
      y += fs * 10;
#endif
    }
    for (int i = 0; i < gObjMsgN && y < IH - bh * 2 - gap * 3 - fs * 10; i++) {
      char lb[128];
      snprintf(lb, sizeof lb, "%.109s", gObjMsg[i]);
      fitText(lb, IW - pad * 2);
      bool bad = strstr(gObjMsg[i], "ОК") == NULL;
      drawText(pad, y, lb, fs, bad ? RGB(255, 170, 120) : RGB(150, 235, 160), 0);
      y += fs * 9;
    }
    if (gObjMsgN == 0) drawText(IW / 2, y, "ЗАГРУЖЕНО МОДЕЛЕЙ: 0", fs, RGB(200, 200, 215), 1);
    int hw = (bw - fs * 3) / 2;
    int by = IH - bh - gap * 3 - fs * 10;
    if (button(x, by, hw, bh, "Перезагрузить", true, RGB(200, 120, 40))) { objLoadConfig(); say("МОДЕЛИ ПЕРЕЗАГРУЖЕНЫ"); }
    if (button(x + hw + fs * 3, by, hw, bh, "Назад", true, RGB(60, 150, 90))) menuPage = 0;
  } else if (menuPage == 2) {
    drawText(IW / 2, y, "ПОЛЯ ЭКРАНА", fs + 1, RGB(255, 210, 120), 1);
    y += fs * 13;
    drawText(IW / 2, y, "ЕСЛИ КРАЙ ЭКРАНА ОБРЕЗАН", fs, RGB(230, 230, 240), 1);
    y += fs * 9;
    drawText(IW / 2, y, "ДОБАВЛЯЙ ОТСТУП, ПОКА ВИДНА ВСЯ РАМКА", fs, RGB(170, 190, 220), 1);
    y += fs * 14;
    for (int k = 0; k < 2; k++) {
      int *v = k == 0 ? &insL : &insR;
      const char *nm;
      if (!rotMode) nm = k == 0 ? "СЛЕВА" : "СПРАВА";
      else if (rotDir > 0) nm = k == 0 ? "СВЕРХУ" : "СНИЗУ";
      else nm = k == 0 ? "СНИЗУ" : "СВЕРХУ";
      drawText(x, y + fs * 4, nm, fs, RGB(235, 235, 245), 0);
      snprintf(b, sizeof b, "%d", *v);
      drawText(x + fs * 46, y + fs * 4, b, fs, RGB(255, 235, 140), 0);
      static const int stp[4] = {-10, -2, 2, 10};
      static const char *lbl[4] = {"-10", "-2", "+2", "+10"};
      int cw = fs * 20, x0 = x + bw - cw * 4 - fs * 6;
      for (int q = 0; q < 4; q++)
        if (button(x0 + q * (cw + fs * 2), y, cw, bh, lbl[q], true, RGB(90, 96, 120))) { *v = clampi(*v + stp[q], 0, 220); saveCfg(); }
      y += bh + gap;
    }
    y += fs * 2;
    int hw = (bw - fs * 3) / 2;
    if (button(x, y, hw, bh, "Авто", true, RGB(200, 120, 40))) { insL = 0; insR = autoInset(); saveCfg(); }
    if (button(x + hw + fs * 3, y, hw, bh, "Готово", true, RGB(60, 150, 90))) { menuPage = 0; saveCfg(); }
  } else {
    drawText(IW / 2, y, "НАЧАТЬ ЗАНОВО?", fs + 1, RGB(255, 120, 110), 1);
    y += fs * 14;
    drawText(IW / 2, y, "ВСЕ ДЕНЬГИ, МАШИНЫ И ПРОГРЕСС", fs, RGB(230, 230, 240), 1);
    y += fs * 10;
    drawText(IW / 2, y, "БУДУТ УДАЛЕНЫ БЕЗ ВОЗВРАТА!", fs, RGB(255, 190, 90), 1);
    y += fs * 16;
    R hr = {x, y, bw, bh};
    bool hold = P.down && inR(hr, P.x, P.y) && inR(hr, P.sx, P.sy);
    button(hr.x, hr.y, hr.w, hr.h, hold ? "УДАЛЯЮ..." : "Держи - удалить всё", true, hold ? RGB(230, 60, 60) : RGB(170, 50, 50));
    if (hold) resetProg += dt / 1.4f; else resetProg = 0;
    fillRect(x, y + bh + fs * 2, bw, fs * 5, RGB(16, 16, 22));
    fillRect(x, y + bh + fs * 2, (int)(bw * clampf(resetProg, 0, 1)), fs * 5, RGB(255, 100, 90));
    if (resetProg >= 1.0f) {
      resetProg = 0;
      resetGame();
      menuPage = 0;
      state = ST_WORLD;
      say("НОВАЯ ИГРА НАЧАТА");
      return;
    }
    y += bh + gap + fs * 6;
    if (button(x, y, bw, bh, "Отмена", true, RGB(50, 54, 66))) menuPage = 0;
  }
  if (menuPage == 2) {   // рамка по краю картинки: подгоняй отступы, пока видны все четыре стороны
    u32 fc = RGB(255, 90, 90);
    fillRect(0, 0, IW, fs, fc); fillRect(0, IH - fs, IW, fs, fc);
    fillRect(0, 0, fs, IH, fc); fillRect(IW - fs, 0, fs, IH, fc);
  }
  toast(IW / 2, IH - fs * 14);
}
static void unloadTow() {
  if (garage.size() >= 4) { say("ГАРАЖ ПОЛОН (МАКС 4). ПРОДАЙ МАШИНУ"); return; }
  garage.push_back(towCar);
  cur = (int)garage.size() - 1;
  hasTow = false;
  say("МАШИНА В ГАРАЖЕ! ЧИНИ, МОЙ И ПРОДАВАЙ");
  saveGame();
  state = ST_WORK; tabW = 0; sel = 0; pvYaw = 0.6f;
}
static void doDeliver() {
  Car &c = garage[cur];
  if (!c.client) {                                  // заказ «купить машину»
    int dz = nearZ - 3, bi = -1, any = -1;
    for (size_t i = 0; i < buys.size(); i++)
      if (buys[i].dest == dz) {
        if (any < 0) any = (int)i;
        if (c.model == buys[i].model && avgc(c) >= buys[i].minAvg) { bi = (int)i; break; }
      }
    if (bi < 0) {
      if (any >= 0) {
        char m2[110];
        snprintf(m2, sizeof m2, "КЛИЕНТУ НУЖНА: %s ОТ %d%%", MOD[buys[any].model].name, buys[any].minAvg);
        say(m2);
      }
      return;
    }
    int own = 0;
    for (size_t q = 0; q < garage.size(); q++) if (!garage[q].client) own++;
    if (own <= 1) { say("НУЖНА ХОТЯ БЫ ОДНА СВОЯ МАШИНА"); return; }
    int price = buys[bi].price;
    money += price;
    buys.erase(buys.begin() + bi);
    garage.erase(garage.begin() + cur);
    cur = 0;
    char m3[96];
    snprintf(m3, sizeof m3, "ПРОДАНО КЛИЕНТУ! +$%d", price);
    say(m3);
    saveGame();
    return;
  }
  char miss[128] = "";
  bool ok = true;
  for (int p = 0; p < NP; p++)
    if ((c.mask & (1 << p)) && c.cond[p] < 85) {
      ok = false;
      if (!miss[0]) snprintf(miss, sizeof miss, "НЕ ГОТОВО: %s", PN[p]);
    }
  for (int k = 0; k < NEX; k++)
    if ((c.mask & EXBIT[k]) && exGet(c, k) < OIL_REQ) { ok = false; if (!miss[0]) snprintf(miss, sizeof miss, "НЕ ГОТОВО: %s", EXNAME[k]); }
  if (c.dirt > 10) { ok = false; if (!miss[0]) snprintf(miss, sizeof miss, "НЕ ГОТОВО: МАШИНА ГРЯЗНАЯ"); }
  if (!ok) { say(miss); return; }
  money += c.reward;
  char b[96];
  snprintf(b, sizeof b, "ЗАКАЗ ВЫПОЛНЕН! +$%d", c.reward);
  garage.erase(garage.begin() + cur);
  cur = 0;
  say(b);
  saveGame();
}

// ---------- Основной цикл ----------
int main(int argc, char **argv) {
  (void)argc; (void)argv;
  if (!gfxInit()) return 1;
#if defined(__ANDROID__) && defined(SDL_MAJOR_VERSION) && SDL_MAJOR_VERSION >= 2
  { const char *ip = SDL_AndroidGetInternalStoragePath(); if (ip && *ip) snprintf(gBase, sizeof gBase, "%s/", ip); }   // сохранения во внутренней памяти приложения
#endif
  rotMode = SH > SW;
  insL = 0; insR = autoInset();   // небольшой запас; точнее настраивается в меню
  loadCfg();
  LW = rotMode ? SH : SW; LH = rotMode ? SW : SH;
  computeSize();
  if (!allocBuffers()) return 1;
  srand((unsigned)time(NULL));
  LDIR = vnorm(v3(0.45f, 0.85f, 0.30f));
  fogCol = RGB(190, 212, 236);
  initWorld();
  objLoadConfig();
  bool loaded = false;
  newGame();                                                     // заготовка мира, пока игрок выбирает мир (ничего не сохраняется)
  state = ST_TITLE;
  if (!gotMarket) genMarket();
  if (!gotOrders) genOrders();
  for (int i = 0; i < 3; i++) if (orders[i].type == 0 && orders[i].car.reward <= 0) genOrder(orders[i]);   // защита от битых заказов
  if (!gotJunk) genJunk();
  if (!gotSellers) genSellers();
  pPos = gotPlayer ? v3(savedX, 0, savedZ) : v3(-30, 0, -12);
  pHead = gotPlayer ? savedH : 0;
  camYaw = pHead; pSpeed = 0;
  inTow = gotPlayer && savedInTow;
  for (int i = 0; i < NNPC; i++) respawnNpc(i);
  memset(&P, 0, sizeof P);
  say("Выбери мир");

  bool running = true;
  Uint32 last = SDL_GetTicks();
  float fpsAcc = 0, fpsWork = 0, perfCool = 0, workSm = 0;       // накопители за полсекунды
  int fpsN = 0, fpsVal = 0, fpsWorkVal = 0, fps3dVal = 0, fpsPrVal = 0;
  while (running) {
    wheelN = quality == 0 ? 10 : (quality == 1 ? 14 : 18);
    if (gPerf >= 2) wheelN = 10;
    {   // уровень 3: временно рисуем на ступень мельче; возвращаем, когда телефон справляется
      int want = (gPerf >= 3 && quality >= 1 && state == ST_WORLD) ? 1 : 0;   // меню и автосалон всегда в полном качестве
      if (want != gResDrop) {
        int oIW = IW, oIH = IH;
        gResDrop = want;
        computeSize();
        if (!allocBuffers()) break;
        if (IW != oIW || IH != oIH) {      // пальцы и джойстик пересчитываем под новый размер картинки
          stickAx = stickAx * IW / oIW; stickAy = stickAy * IH / oIH;
          P.x = P.x * IW / oIW; P.y = P.y * IH / oIH; P.sx = P.sx * IW / oIW; P.sy = P.sy * IH / oIH;
          P.cx = P.cx * IW / oIW; P.cy = P.cy * IH / oIH;
        }
      }
    }
    if (gApplyQ) { gApplyQ = false; computeSize(); if (!allocBuffers()) break; stickOn = false; }
    Uint32 now = SDL_GetTicks();
    fpsAcc += (float)(now - last); fpsN++;
    if (fpsAcc >= 500.0f) {
      fpsVal = (int)(fpsN * 1000.0f / fpsAcc + 0.5f);
      fpsWorkVal = (int)(fpsWork / fpsN + 0.5f);
      fps3dVal = (int)(gProf3D / fpsN + 0.5f); fpsPrVal = (int)(gProfPr / fpsN + 0.5f); gProf3D = 0; gProfPr = 0;
      fpsAcc = 0; fpsWork = 0; fpsN = 0;
      // авто-упрощение: если кадр считается дольше ~34 мс - выключаем самое дорогое; вернём, когда станет заметно легче
      workSm = workSm == 0 ? (float)fpsWorkVal : workSm * 0.5f + fpsWorkVal * 0.5f;
      perfCool += 0.5f;
      if (!autoPerf) gPerf = 0;
      else if (workSm > 34.0f && gPerf < (quality >= 1 ? 3 : 2) && perfCool > 1.0f) { gPerf++; perfCool = 0; workSm = 0; }
      else if (workSm > 0 && workSm < (gPerf >= 3 ? 17.0f : 11.0f) && gPerf > 0 && perfCool > 8.0f) { gPerf--; perfCool = 0; workSm = 0; }
    }
    float dt = clampf((now - last) / 1000.0f, 0.001f, 0.05f);
    last = now;
    gTime += dt;
    if (state == ST_WORLD) updateDaylight(); else { gLight = 1.0f; gNight = 0.0f; fogCol = RGB(190, 212, 236); }
    updateShipping(dt);
    if (hintT > 0 && state == ST_WORLD) hintT -= dt;
    if (state == ST_WORLD) { dayT += dt; if (dayT >= 240.0f) newDay(); }
    static float autoT = 0;
    autoT += dt;
    if (autoT >= 15.0f && (state != ST_WORLD || fabsf(pSpeed) < 1.0f || autoT >= 60.0f)) { autoT = 0; saveGame(); }   // автосохранение (не во время езды)
    if (gMsgT > 0) gMsgT -= dt;
    P.pressed = false; P.clicked = false; P.dx = P.dy = 0;
    bool released = false;
    Ev e;
    while (pollEv(e)) {
      if (e.type == 0) running = false;
      else if (e.type == 5) saveGame();
      else if (e.type == 4) {
        if (state == ST_WORLD) { state = ST_MENU; menuPage = 0; resetProg = 0; pSpeed = 0; stickOn = false; stX = stY = 0; }
        else if (state == ST_MENU) { if (menuPage != 0) { if (menuPage == 2) saveCfg(); menuPage = 0; } else state = ST_WORLD; }
        else if (state == ST_TITLE) gQuit = true;
        else if (state == ST_WASH) finishWash();
        else if (state == ST_SHOP) { state = shopReturn; saveGame(); }
        else { state = ST_WORLD; saveGame(); }
      }
      else {
        int mx, my;
        mapPt(e.x, e.y, mx, my);
        if (e.type == 1) { P.down = true; P.pressed = true; P.x = P.sx = mx; P.y = P.sy = my; }
        else if (e.type == 3) { if (P.down) { P.dx += mx - P.x; P.dy += my - P.y; } P.x = mx; P.y = my; }
        else if (e.type == 2) { P.x = mx; P.y = my; P.cx = mx; P.cy = my; P.down = false; P.clicked = !gSkipUp; gSkipUp = false; released = true; }
      }
    }
    if (gQuit) running = false;
    setClipRect(0, 0, IW, IH);
    if (state == ST_WORLD) {
      // ввод: кнопка действия и плавающий джойстик
      R ar = actionRect();
      if (P.pressed && inR(hudBtn(3), P.sx, P.sy)) {
        state = ST_SHOP; shopReturn = ST_WORLD; shopTab = 0; shopModel = garage[cur].model;
        stickOn = false; stX = stY = 0; pSpeed = 0;
        gSkipUp = P.down; P.clicked = false; P.pressed = false;
      }
      else if (P.pressed && inR(miniRect(), P.sx, P.sy)) {
        state = ST_MAP;
        stickOn = false; stX = stY = 0; pSpeed = 0;
        gSkipUp = P.down; P.clicked = false; P.pressed = false;
      }
      else if (P.pressed && inR(hudBtn(4), P.sx, P.sy)) { taxiToggle(); P.pressed = false; }
      else if (P.pressed && inR(menuBtnRect(), P.sx, P.sy)) {
        state = ST_MENU; menuPage = 0; resetProg = 0;
        stickOn = false; stX = stY = 0; pSpeed = 0;
        gSkipUp = P.down; P.clicked = false; P.pressed = false;
      }
      else if (P.pressed && inR(towBtnRect(), P.sx, P.sy)) {
        inTow = !inTow;
        if (inTow && taxi.on) { taxi.on = false; taxi.st = 0; gWP.on = false; }
        pSpeed = 0; stickOn = false; stX = stY = 0;
        say(inTow ? "ТЫ В ЭВАКУАТОРЕ: К СВАЛКЕ" : "ТЫ СНОВА В СВОЕЙ МАШИНЕ");
        P.pressed = false;
      }
      else if (P.pressed && inR(ordBtnRect(), P.sx, P.sy)) {
        int ncl = 0;
        ncl = activeOrders();
        state = ST_ORD; oTab = ncl == 0 ? 0 : 1; aSel = 0;
        for (size_t i = 0; i < garage.size(); i++) if ((int)i == cur && garage[i].client) { aSel = 0; }
        { int k = 0; for (size_t i = 0; i < garage.size(); i++) if (garage[i].client) { if ((int)i == cur) aSel = k; k++; } }
        stickOn = false; stX = stY = 0; pSpeed = 0;
        gSkipUp = P.down; P.clicked = false; P.pressed = false;
      }
      else if (P.pressed && qRect.w > 0 && inR(qRect, P.sx, P.sy)) { qCollapsed = !qCollapsed; P.pressed = false; }
      if (P.pressed) {
        if (nearZ >= 0 && inR(ar, P.sx, P.sy)) {
          stickOn = false;
          int k = nearZ;
          pSpeed = 0; stX = stY = 0;
          if (k == 0) { if (inTow && hasTow) unloadTow(); else { state = ST_WORK; tabW = 0; sel = 0; pvYaw = 0.6f; } }
          else if (k == 7) { state = ST_JUNK; jSel = 0; pvYaw = 0.6f; }
          else if (k == 8) { state = ST_FUEL; pvYaw = 0.6f; fuelPay = 0; fuelSpent = 0; }
          else if (k >= 9) { state = ST_SELLER; selK = k - 9; pvYaw = 0.6f; }
          else if (k == 1) {
            if (garage[cur].dirt < 3) say("МАШИНА И ТАК ЧИСТАЯ");
            else if (money < 10) say("НЕ ХВАТАЕТ ДЕНЕГ ($10)");
            else { money -= 10; startWash(); saveGame(); }
          } else if (k == 2) { state = ST_DEAL; dTab = 0; pvYaw = 0.6f; }
          else doDeliver();
          gSkipUp = P.down && state != ST_WORLD;
          P.pressed = false;
          P.clicked = false;
        } else if (P.sy > IH * 30 / 100) {
          stickOn = true; stickAx = P.sx; stickAy = P.sy; stX = stY = 0; hintT = 0;
        }
      }
      if (stickOn) {
        if (P.down) {
          float R0 = fs * 22.0f;
          stX = clampf((P.x - stickAx) / R0, -1, 1);
          stY = clampf((P.y - stickAy) / R0, -1, 1);
        } else { stickOn = false; stX = stY = 0; }
      }
      if (state == ST_WORLD) { updateWorld(dt); updateTraffic(dt); }
      // камера и рендер
      Car &car = garage[cur];
      V3 fw = v3(sinf(camYaw), 0, cosf(camYaw));
      V3 eye = pPos - fw * (inTow ? 11.0f : 8.5f) + v3(0, inTow ? 5.4f : 4.3f, 0);
      if (!inTow && car.bal < 40.0f && fabsf(pSpeed) > 6.0f) {
        float amp = (1.0f - car.bal / 40.0f) * fminv(1.0f, fabsf(pSpeed) / 20.0f) * 0.12f;
        eye.x += sinf(gTime * 47.0f) * amp;
        eye.y += sinf(gTime * 61.0f) * amp;
      }
      V3 tgt = pPos + fw * 5.0f + v3(0, 0.6f, 0);
      focal = fminv((float)IW, (float)IH) * 1.1f;
      vcx = IW * 0.5f; vcy = IH * 0.48f;
      fogA = 70; fogB = 230;
      setCamera(eye, tgt);
      fillSky();
      clearDepth();
      drawWorldStatic();
      if (inTow) drawTow(pPos, pHead, hasTow, towCar);
      else { drawCar(car, pPos, pHead, -1); carNightLights(pPos, pHead, true); }
      if (aaOn && quality >= 1 && gPerf == 0) smoothRegion(0, 0, IW, IH);
      drawWorldHUD();
      if (gCopStop > 0) drawTextSh(IW / 2, IH * 26 / 100, "ПОЛИЦИЯ: ПРОВЕРКА ДОКУМЕНТОВ...", fs + 2, RGB(255, 225, 90), 1);
      if (licenseExpired()) {                                   // права просрочены: баннер и кнопка экзамена
        drawTextSh(IW / 2, IH * 36 / 100, "ПРАВА ПРОСРОЧЕНЫ: ПОЛИЦИЯ ОШТРАФУЕТ НА 50%", fs + 1, RGB(255, 90, 80), 1);
        int bw0 = imin(IW - fs * 20, fs * 120);
        if (button(IW / 2 - bw0 / 2, IH * 36 / 100 + fs * 14, bw0, fs * 17, "СДАТЬ ЭКЗАМЕН НА ПРАВА", true, RGB(60, 110, 200))) startExam();
      }
      if (nearZ >= 0) {
        const char *lab = zoneAction(nearZ);
        if (nearZ == 0 && inTow && hasTow) lab = "РАЗГРУЗИТЬ";
        if (nearZ >= 3 && nearZ < 7 && !garage[cur].client) lab = "ПРОДАТЬ КЛИЕНТУ";
        button(ar.x, ar.y, ar.w, ar.h, lab, true, nearZ == 1 ? RGB(40, 150, 190) : (nearZ == 8 ? RGB(210, 60, 60) : (nearZ >= 3 ? RGB(230, 140, 30) : RGB(60, 150, 90))));
      }
    } else if (state == ST_WORK) {
      if (P.pressed && inR(VW, P.sx, P.sy)) dragView = true;
      if (dragView && P.down) pvYaw += P.dx * 0.012f; else pvYaw += dt * 0.6f;
      if (!P.down) dragView = false;
      menuWorkshop(dt);
    } else if (state == ST_DEAL) {
      if (P.pressed && inR(VW, P.sx, P.sy)) dragView = true;
      if (dragView && P.down) pvYaw += P.dx * 0.012f; else pvYaw += dt * 0.6f;
      if (!P.down) dragView = false;
      menuDealer();
    } else if (state == ST_SHOP) {
      menuShop();
    } else if (state == ST_MAP) {
      menuMap();
    } else if (state == ST_SELLER) {
      if (P.pressed && inR(VW, P.sx, P.sy)) dragView = true;
      if (dragView && P.down) pvYaw += P.dx * 0.012f; else pvYaw += dt * 0.6f;
      if (!P.down) dragView = false;
      menuSeller();
    } else if (state == ST_TITLE) {
      titleScreen(dt);
    } else if (state == ST_EXAM) {
      examScreen(dt);
    } else if (state == ST_MENU) {
      menuGame(dt);
    } else if (state == ST_FUEL) {
      if (P.pressed && inR(VW, P.sx, P.sy)) dragView = true;
      if (dragView && P.down) pvYaw += P.dx * 0.012f; else pvYaw += dt * 0.6f;
      if (!P.down) dragView = false;
      menuFuel(dt);
    } else if (state == ST_JUNK) {
      if (P.pressed && inR(VW, P.sx, P.sy)) dragView = true;
      if (dragView && P.down) pvYaw += P.dx * 0.012f; else pvYaw += dt * 0.6f;
      if (!P.down) dragView = false;
      menuJunk();
    } else if (state == ST_ORD) {
      menuOrders();
    } else if (state == ST_WASH) {
      menuWash(dt);
    }
    (void)released;
    if (fpsOn) {
      char fb2[96];
      if (gPerf > 0) snprintf(fb2, sizeof fb2, "FPS %d  %d МС  3Д%d ВЫВОД%d  A%d", fpsVal, fpsWorkVal, fps3dVal, fpsPrVal, gPerf);
      else snprintf(fb2, sizeof fb2, "FPS %d  %d МС  3Д%d ВЫВОД%d", fpsVal, fpsWorkVal, fps3dVal, fpsPrVal);
      u32 fcol = fpsVal >= 35 ? RGB(120, 240, 130) : (fpsVal >= 24 ? RGB(255, 220, 90) : RGB(255, 100, 90));
      if (state == ST_WORLD) drawTextSh(IW * 55 / 100, IH - fs * 11, fb2, fs, fcol, 1);      // снизу по центру: не мешает мини-карте, стрелке и панели такси
      else drawTextSh(IW * 20 / 100, IH - fs * 9, fb2, fs, fcol, 1);      // на экранах магазина и меню плашка внизу слева, чтобы не налезать на деньги и кнопки
    }
    Uint32 tp0 = SDL_GetTicks();
    gfxPresent();
    gProfPr += (float)(SDL_GetTicks() - tp0);
    Uint32 spent = SDL_GetTicks() - now;
    fpsWork += (float)spent;
    if (spent < 25) SDL_Delay(25 - spent);
  }
  saveGame();
  free(fb);
  free(zb);
  gfxQuit();
  return 0;
}
